SELECT
COUNT(*) AS totalCount,
SUM(CASE WHEN type = 'in'  THEN amount ELSE 0 END) AS totalIncome,
SUM(CASE WHEN type = 'out' THEN amount ELSE 0 END) AS totalExpense,
SUM(CASE WHEN type = 'in'  THEN amount ELSE 0 END) -
SUM(CASE WHEN type = 'out' THEN amount ELSE 0 END) AS balance
FROM bill_record


        bill_book_id = #{billId}


       and record_time BETWEEN #{startTime} AND #{endTime}


    and openid = #{openid}
